import {days,periods,validate,normalize,parseLocalDate,dateKey,currentWeek,occurs,merge,exportICS} from './core.js';
const $=s=>document.querySelector(s),E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={calendar:'M5 5h14v16H5z M8 3v4m8-4v4M5 10h14M8 14h2m4 0h2m-8 4h2',sun:'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',upload:'M12 16V3m-5 5 5-5 5 5M4 14v6h16v-6',settings:'M4 6h16M4 12h16M4 18h16M8 3v6m8 0v6m-6 0v6',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z m-4 9 3 3 5-6',phone:'M8 2h8v20H8z M11 18h2',plus:'M12 5v14M5 12h14',left:'m14 6-6 6 6 6',right:'m10 6 6 6-6 6',info:'M12 10v6m0-10v1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',close:'m6 6 12 12M6 18 18 6'};
function hydrateIcons(){document.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[el.dataset.icon]||icons.calendar}"/></svg>`;});}hydrateIcons();
const storageKey='campus-schedule-web-v1';let state,week=2,tab='week',preview=null,editing=null;let toastTimer;
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
function save(next){try{localStorage.setItem(storageKey,JSON.stringify(next));state=next;render();return true;}catch{toast('保存失败，可能存储空间不足。当前修改尚未保存，请先导出备份。');return false;}}
try{const saved=localStorage.getItem(storageKey);if(saved){const data=JSON.parse(saved);if(!Array.isArray(data.courses)||data.courses.some(c=>validate(c))||!Array.isArray(data.periods)||data.periods.length!==12)throw Error();state=data;}else state={courses:[],semesterStart:'',periods,weekends:true};}catch{state={courses:[],semesterStart:'',periods,weekends:true};toast('原有课表读取失败，未覆盖原数据。可在导入页恢复 JSON 备份。');}
try{if(!localStorage.getItem(storageKey))localStorage.setItem(storageKey,JSON.stringify(state));}catch{toast('浏览器无法保存数据，请导出备份。');}
week=Math.min(30,Math.max(1,currentWeek(state.semesterStart)||2));
const colors=[['#eef2fb','#45649c','#dbe4f5'],['#e8f4f0','#35725f','#d8ebe3'],['#fff3e6','#9e6d31','#f3e5d3'],['#f1edfa','#78649e','#e4ddf2']];
function palette(c){if(['中国近现代史纲要','形势与政策','职业生涯发展和就业指导','创新创业基础'].includes(c.name))return colors[1];return colors[[...c.name].reduce((n,ch)=>n+ch.charCodeAt(0),0)%colors.length];}
function setTab(name){tab=['week','today','import','settings'].includes(name)?name:'week';document.querySelectorAll('.view').forEach(el=>el.hidden=el.id!==tab+'-view');document.querySelectorAll('[data-tab]').forEach(el=>el.classList.toggle('active',el.dataset.tab===tab));try{history.replaceState(null,'','#'+tab);}catch{}render();}
document.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>setTab(el.dataset.tab));document.querySelectorAll('[data-open-settings]').forEach(el=>el.onclick=()=>setTab('settings'));
function render(){renderWeek();renderToday();if(tab==='settings')renderSettings();}
function renderWeek(){
 $('#week-label').textContent=`第 ${week} 周`;const start=parseLocalDate(state.semesterStart),weekStart=start?new Date(start):null;if(weekStart)weekStart.setDate(start.getDate()+(week-1)*7);const end=weekStart?new Date(weekStart):null;if(end)end.setDate(end.getDate()+6);$('#week-dates').textContent=weekStart?`${weekStart.getMonth()+1}月${weekStart.getDate()}日 — ${end.getMonth()+1}月${end.getDate()}日`:'按教学周查看课程';$('#semester-notice').hidden=!!start;$('#previous-week').disabled=week<=1;$('#next-week').disabled=week>=30;$('#weekends').checked=state.weekends!==false;
 const count=state.weekends===false?5:7,courses=state.courses.filter(c=>occurs(c,week));$('#week-summary').textContent=`本周 ${courses.length} 条上课安排 · ${new Set(courses.map(c=>c.name)).size} 门课程`;
 let html='<div class="grid-header" style="grid-column:1;grid-row:1">节次</div>';
 for(let d=1;d<=count;d++){const date=weekStart?new Date(weekStart):null;if(date)date.setDate(date.getDate()+d-1);const today=date&&dateKey(date)===dateKey(new Date());html+=`<div class="grid-header ${today?'is-today':''}" style="grid-column:${d+1};grid-row:1"><strong>${days[d-1]}</strong><small>${date?date.getDate()+'日':''}</small></div><div class="grid-background" style="grid-column:${d+1};grid-row:2 / 14"></div>`;}
 for(let p=1;p<=12;p++)html+=`<div class="period-label" style="grid-column:1;grid-row:${p+1}"><span>${p}</span><small>${E(state.periods[p-1][0])}</small></div>`;
 for(const c of courses.filter(c=>c.weekday<=count)){const conflict=courses.some(other=>other.id!==c.id&&other.weekday===c.weekday&&other.startPeriod<=c.endPeriod&&other.endPeriod>=c.startPeriod);const [bg,ink,border]=palette(c);html+=`<button class="course-block ${conflict?'conflict':''}" data-course="${E(c.id)}" style="--course-bg:${bg};--course-ink:${ink};--course-border:${border};grid-column:${c.weekday+1};grid-row:${c.startPeriod+1} / ${c.endPeriod+2}" aria-label="${E(c.name)}，${days[c.weekday-1]}，${c.startPeriod}到${c.endPeriod}节"><strong>${E(c.name)}</strong><span>${E(c.room||'地点待定')}</span><span class="course-period">${conflict?'安排重叠 · ':''}${c.startPeriod}—${c.endPeriod}节</span></button>`;}
 if(!courses.length)html+='<span class="empty-week-note">这一周没有课程安排</span>';$('#schedule-grid').style.setProperty('--days',count);$('#schedule-grid').innerHTML=html;
}
$('#schedule-grid').onclick=event=>{const button=event.target.closest('[data-course]');if(button)openEditor(state.courses.find(c=>c.id===button.dataset.course),'state');};
$('#previous-week').onclick=()=>{week=Math.max(1,week-1);renderWeek();};$('#next-week').onclick=()=>{week=Math.min(30,week+1);renderWeek();};$('#go-current').onclick=()=>{const current=currentWeek(state.semesterStart);if(current===null){toast('请先设置第一周的周一');setTab('settings');}else if(current<1||current>30){toast('今天不在本学期的 1—30 周内');}else{week=current;renderWeek();}};$('#weekends').onchange=event=>save({...state,weekends:event.target.checked});
function renderToday(){const now=new Date();$('#today-date').textContent=now.toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'});const current=currentWeek(state.semesterStart);if(current===null){$('#today-content').innerHTML='<div class="panel empty-state"><h2>先告诉课表，哪天开学</h2><p>设置第一周的周一后，才能准确显示今天的课程。</p><button class="primary-button" data-setup>设置日期</button></div>';$('#today-content [data-setup]').onclick=()=>setTab('settings');return;}if(current<1){$('#today-content').innerHTML='<div class="panel empty-state"><h2>学期还未开始</h2><p>可以在我的课表中提前查看课程。</p></div>';return;}
 const weekday=(now.getDay()+6)%7+1,list=state.courses.filter(c=>c.weekday===weekday&&occurs(c,current)).sort((a,b)=>a.startPeriod-b.startPeriod);$('#today-content').innerHTML=list.length?`<p>第 ${current} 周 · ${list.length} 条课程安排</p><div class="today-list">${list.map(c=>{const [first]=state.periods[c.startPeriod-1],[,last]=state.periods[c.endPeriod-1];const time=now.getHours()*60+now.getMinutes(),minutes=s=>+s.split(':')[0]*60+ +s.split(':')[1];const status=time<minutes(first)?'待上课':time<=minutes(last)?'正在上课':'已结束';return `<button class="panel today-card" data-course="${E(c.id)}" style="text-align:left"><div class="today-card-time">${first}<small>${last}</small></div><div><h2>${E(c.name)}</h2><p>${E(c.room||'地点待定')}</p><p>${E(c.teacher)} · ${c.startPeriod}—${c.endPeriod}节 <span class="status-label">${status}</span></p></div></button>`;}).join('')}</div>`:'<div class="panel empty-state"><h2>今天没有课程</h2><p>留一点时间给自己。</p></div>';$('#today-content').querySelectorAll('[data-course]').forEach(button=>button.onclick=()=>openEditor(state.courses.find(c=>c.id===button.dataset.course),'state'));}
function renderSettings(){$('#semester-start').value=state.semesterStart||'';$('#period-settings').innerHTML=state.periods.map((p,i)=>`<div class="period-row"><span>第 ${i+1} 节</span><input type="time" aria-label="第${i+1}节开始时间" value="${E(p[0])}" name="start-${i}" required><span>—</span><input type="time" aria-label="第${i+1}节结束时间" value="${E(p[1])}" name="end-${i}" required></div>`).join('');}
$('#settings-form').onsubmit=event=>{event.preventDefault();const start=$('#semester-start').value;if(start&&parseLocalDate(start)?.getDay()!==1){toast('第一周起始日期请选择周一');return;}const times=Array.from({length:12},(_,i)=>[$(`[name="start-${i}"]`).value,$(`[name="end-${i}"]`).value]);if(times.some(([a,b])=>!a||!b||a>=b)){toast('请检查每节课的起止时间');return;}if(save({...state,semesterStart:start,periods:times}))toast('学期与作息已保存');};
function openEditor(course,location){editing={course:{...course},location};const form=$('#course-form');for(const key of ['name','weekday','teacher','startPeriod','endPeriod','weeks','room'])form.elements[key].value=course[key]??'';$('#course-error').hidden=true;$('#delete-course').hidden=location==='new';$('#course-dialog').showModal();}
$('#add-course').onclick=()=>openEditor(normalize({name:'',weekday:1,startPeriod:1,endPeriod:2,weeks:'1-16'}),'new');
$('#course-form').onsubmit=event=>{event.preventDefault();const form=$('#course-form');const c={...editing.course};for(const key of ['name','weekday','teacher','startPeriod','endPeriod','weeks','room'])c[key]=form.elements[key].value;for(const k of ['weekday','startPeriod','endPeriod'])c[k]=+c[k];const error=validate(c);if(error){$('#course-error').hidden=false;$('#course-error').textContent=error;return;}
 if(editing.location==='preview'){preview.courses=preview.courses.map(old=>old.id===c.id?c:old);renderPreview();}else{const courses=editing.location==='new'?[...state.courses,c]:state.courses.map(old=>old.id===c.id?c:old);if(!save({...state,courses}))return;}$('#course-dialog').close();};
$('#delete-course').onclick=()=>$('#confirm-dialog').showModal();$('#cancel-delete').onclick=()=>$('#confirm-dialog').close();$('#confirm-delete').onclick=()=>{if(editing.location==='preview'){preview.courses=preview.courses.filter(c=>c.id!==editing.course.id);renderPreview();}else if(!save({...state,courses:state.courses.filter(c=>c.id!==editing.course.id)}))return;$('#confirm-dialog').close();$('#course-dialog').close();};document.querySelectorAll('[data-close-dialog]').forEach(button=>button.onclick=()=>button.closest('dialog').close());
$('#install-help').onclick=()=>$('#help-dialog').showModal();
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
$('#export-json').onclick=()=>download('校园课表备份.json',JSON.stringify(state,null,2));$('#export-ics').onclick=()=>{try{download('校园课表.ics',exportICS(state),'text/calendar;charset=utf-8');}catch(e){toast(e.message);}};
$('#download-template').onclick=()=>download('课表导入模板.csv','\uFEFF课程,星期,开始节,结束节,周次,教室,教师\r\n工程力学,3,1,2,"2-3,6-12",敦文园E-213,梁小光\r\n','text/csv;charset=utf-8');
$('#load-sample').onclick=async()=>{try{preview={courses:(await(await fetch('./sample.json')).json()).map(normalize),warnings:['这是虚构示例课程。请导入你自己的课表。'],rawText:'示例含 2 门课程。'};renderPreview();}catch{toast('无法加载样本，请联网后重试。');}};
function renderPreview(){if(!preview){$('#import-preview').innerHTML='';return;}const invalid=preview.courses.some(c=>validate(c));$('#import-preview').innerHTML=`<div class="preview-heading"><h2>校对 ${preview.courses.length} 条安排</h2><button id="confirm-import" class="primary-button" ${invalid||!preview.courses.length?'disabled':''}>确认追加到课表</button></div>${preview.warnings.map(w=>`<div class="notice">${E(w)}</div>`).join('')}<div class="preview-list">${preview.courses.map(c=>`<div class="preview-row ${validate(c)?'invalid':''}"><div><strong>${E(c.name||'课程名待填写')}</strong><p>${E(days[c.weekday-1]||'星期待校对')} · ${c.startPeriod}—${c.endPeriod}节 · ${E(c.weeks)}周</p><p>${E(c.room||'地点待定')} · ${E(c.teacher||'教师待填写')}</p>${validate(c)?`<p style="color:#a64235">${E(validate(c))}</p>`:''}</div><div class="preview-actions"><button class="text-button" data-edit="${E(c.id)}">校对</button><button class="text-button" data-remove="${E(c.id)}">移除</button></div></div>`).join('')}</div><details class="panel" style="margin-top:20px"><summary>查看识别原文</summary><pre class="raw-text">${E(preview.rawText||'')}</pre></details>`;
 $('#confirm-import').onclick=()=>{const courses=merge(state.courses,preview.courses);const count=courses.length-state.courses.length;let next={...state,courses};if(preview.backup){next={...next,semesterStart:preview.backup.semesterStart||state.semesterStart,periods:preview.backup.periods||state.periods};}if(save(next)){preview=null;renderPreview();toast(`已追加 ${count} 条安排，重复条目已跳过`);setTab('week');}};$('#import-preview').querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openEditor(preview.courses.find(c=>c.id===b.dataset.edit),'preview'));$('#import-preview').querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{preview.courses=preview.courses.filter(c=>c.id!==b.dataset.remove);renderPreview();});}
$('#file-input').onchange=async event=>{const file=event.target.files[0];if(!file)return;$('#import-error').hidden=true;$('#import-progress').hidden=false;$('#file-input').disabled=true;preview=null;renderPreview();const progress=text=>$('#import-progress').textContent=text;try{progress('正在读取文件：'+file.name+'…');const {readFile}=await Promise.race([import('./importers.js?v=3'),new Promise((_,reject)=>setTimeout(()=>reject(Error('识别组件加载超时，请联网后刷新页面重试。')),20000))]);preview=await readFile(file,state,progress);renderPreview();}catch(e){$('#import-error').textContent=e.message||'无法读取文件，请换用 CSV 或手动添加课程';$('#import-error').hidden=false;}finally{$('#import-progress').hidden=true;$('#file-input').disabled=false;event.target.value='';}};
setTab(location.hash.slice(1)||'week');window.campusAppReady=true;
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
